import type { HelpTopic } from "../../../shared/types";

export const workbenchHelp: HelpTopic[] = [
  { id:"projects-approval", section:"Projects", title:"Why approve a project?", body:"Registration creates an explicit filesystem boundary for the Workbench. Use an absolute Windows directory such as C:\\dev\\my-project, preferably the repository root. Only approved projects can be selected for tasks or Git actions." },
  { id:"projects-safety", section:"Projects", title:"Project safety and removal", body:"Choose the narrowest useful project root. Removing a project revokes it from the Workbench list; it does not delete the directory. The current backend supports remove and re-add rather than in-place path editing." },
  { id:"tasks-basics", section:"Tasks", title:"What does a change task do?", body:"A change task asks the selected local coding role to inspect an approved project, run permitted commands, propose or apply scoped changes, and report results. Review generated changes before committing." },
  { id:"tasks-request", section:"Tasks", title:"Writing a useful request", body:"Use this structure:\nObjective: what should change.\nConstraints: behavior or files that must remain stable.\nAcceptance criteria: observable completion conditions.\nTests to run: exact commands where known.\nLikely files/modules: optional pointers." },
  { id:"tasks-output", section:"Tasks", title:"Results and approvals", body:"Task details can include progress events, changed files, command output, test results, and patches. When the backend requests approval, inspect the command or file action and explicitly approve or deny it. A completed task is not automatically committed." },
  { id:"git-status", section:"Git", title:"Status and diffs", body:"Status summarizes the working tree. Working diff shows unstaged changes; staged diff shows changes already added to the index. Empty output generally means there are no changes in that view." },
  { id:"git-branch", section:"Git", title:"Branches", body:"Create or switch to a focused branch before committing. Use a valid short name such as feature/improve-login and avoid spaces. Existing backend behavior determines whether the name creates a new branch or switches to one." },
  { id:"git-commit", section:"Git", title:"Stage and commit", body:"Stage all and commit adds current project changes and creates a local commit. Use an imperative message that explains the outcome, for example: Improve OAuth connection diagnostics." },
  { id:"git-push", section:"Git", title:"Pushing safely", body:"Push sends the current local branch to its configured remote and affects collaborators. The Workbench asks for confirmation; verify the selected project, current branch, diff, tests, and intended remote workflow first." },
  { id:"git-workflow", section:"Git", title:"Recommended workflow", body:"Create or select a branch → inspect generated changes → run tests → review working diff → stage and commit → inspect staged/commit state → push the current branch." }
];
